        if prev and 'bid' in prev:
            max_prev_bid = max(max_prev_bid, prev['bid'])

    if hp <= 2:
        bid = min(budget, SALARY * 0.95)
    elif hp <= 4:
        bid = min(budget, SALARY * 0.7)
